import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/other/vm-fix-ip.html","title":"Fix VM IP","lang":"en-US","frontmatter":{},"git":{"updatedTime":1750586115000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":7,"url":"https://github.com/hifat"}],"changelog":[{"hash":"18f4210595839548d315fcf5c604fa91fabd78f3","time":1750586115000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add binary secure content"},{"hash":"7718fc11e5d068a0d0b6184de58bbfee2f0c89d7","time":1750581364000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add topic fo vm ip content"},{"hash":"7025aab1e79b4ebf4c81676a90747cfd050e3f6d","time":1750581300000,"email":"logmanxsa@gmail.com","author":"hifat","message":"fix vm ip content"},{"hash":"669bd0fa3fb23cc72accc1202d7434544b973cc6","time":1750580642000,"email":"logmanxsa@gmail.com","author":"hifat","message":"fix vm ip content"},{"hash":"b6079f5d0bb702fb4050709d370ad04d7f7544c1","time":1750580460000,"email":"logmanxsa@gmail.com","author":"hifat","message":"fix vm ip content"},{"hash":"dd8b865790ee716f5975a0444cd25880dceeefb5","time":1750580192000,"email":"logmanxsa@gmail.com","author":"hifat","message":"fix vm ip content"},{"hash":"4c8262a657cff1234633877d7a47533c2a1e1459","time":1750579983000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add fx vm ip content"}]},"filePathRelative":"other/vm-fix-ip.md"}`),a={name:`vm-fix-ip.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="fix-vm-ip" tabindex="-1"><a class="header-anchor" href="#fix-vm-ip"><span>Fix VM IP</span></a></h1><p>ปัญหาที่คุณเจอคือ IP ของ VM เปลี่ยนทุกครั้งที่รีสตาร์ทเครื่องจริง (host) ซึ่งทำให้ config ที่อ้างอิง IP พัง เช่น Jenkins URL, webhook, etc. การใช้ Domain name มาช่วยอ้างแทน IP เป็นทางออกที่ดีมาก แต่ต้อง จับคู่ domain → IP แบบ dynamic ให้ได้ด้วย</p><p>⸻</p><p>🔧 ทางออกที่ผมแนะนำมี 3 แนวทาง ขึ้นกับว่าอยากง่าย, ยืดหยุ่น หรือถาวร:</p><p>⸻</p><p>✅ วิธีที่ 1: Fix IP Address ของ VM (ดีที่สุดถ้าทำได้)</p><p>ให้ VM ใช้ Static IP ภายใน network เช่น 192.168.1.200 แล้วใช้ hosts หรือ DNS local ชี้ domain → IP ถาวร</p><p>วิธีทำ:</p><ol><li>เข้าไป config network ใน UTM VM → เปลี่ยนเป็น Bridged Mode</li><li>ตั้งค่า IP ภายใน VM ให้เป็น static เช่นใน /etc/netplan/*.yaml (ถ้าใช้ Ubuntu)</li></ol><div class="language-yaml line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#85E89D;">network</span><span style="color:#E1E4E8;">:</span></span></span>
<span class="line"><span class="line"><span style="color:#85E89D;">  version</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">2</span></span></span>
<span class="line"><span class="line"><span style="color:#85E89D;">  ethernets</span><span style="color:#E1E4E8;">:</span></span></span>
<span class="line"><span class="line"><span style="color:#85E89D;">    enp0s1</span><span style="color:#E1E4E8;">:  </span><span style="color:#6A737D;"># ตรวจชื่อ interface ด้วย \`ip a\`</span></span></span>
<span class="line"><span class="line"><span style="color:#85E89D;">      dhcp4</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">no</span></span></span>
<span class="line"><span class="line"><span style="color:#85E89D;">      addresses</span><span style="color:#E1E4E8;">:</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">        - </span><span style="color:#9ECBFF;">192.168.1.200/24</span></span></span>
<span class="line"><span class="line"><span style="color:#85E89D;">      nameservers</span><span style="color:#E1E4E8;">:</span></span></span>
<span class="line"><span class="line"><span style="color:#85E89D;">        addresses</span><span style="color:#E1E4E8;">: [</span><span style="color:#79B8FF;">1.1.1.1</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">8.8.8.8</span><span style="color:#E1E4E8;">]</span></span></span>
<span class="line"><span class="line"><span style="color:#85E89D;">      routes</span><span style="color:#E1E4E8;">:</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">        - </span><span style="color:#85E89D;">to</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">default</span></span></span>
<span class="line"><span class="line"><span style="color:#85E89D;">          via</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">192.168.1.1</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>สั่ง:</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">sudo</span><span style="color:#9ECBFF;"> netplan</span><span style="color:#9ECBFF;"> apply</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="3"><li>จากนั้นคุณสามารถใช้ hosts หรือ DNS ภายในชี้ jenkins.local → 192.168.1.200</li></ol><p>⸻</p><p>โดยรวม การตั้งค่า Static IP บน Debian กับ Ubuntu ใกล้เคียงกันมาก แต่มีความต่างนิดหน่อยขึ้นอยู่กับว่าใช้ระบบ network แบบไหน:</p><p>⸻</p><p>✅ กรณีที่คุณใช้ Ubuntu Server (20.04+), Debian 10+</p><p>ส่วนใหญ่ใช้ระบบ Netplan เหมือนกัน</p><p>⸻</p><p>⚠️ แต่ถ้า Debian ของคุณยังใช้ ifupdown (interfaces file)</p><p>อันนี้จะต้อง config ที่ /etc/network/interfaces แทน เช่น:</p><div class="language-ini line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="ini"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#6A737D;"># The loopback network interface</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">auto lo</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">iface lo inet loopback</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># The primary network interface</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">auto enp0s1</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">iface enp0s1 inet static</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">    address 192.168.1.200</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">    netmask 255.255.255.0</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">    gateway 192.168.1.1</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">    dns-nameservers 1.1.1.1 8.8.8.8</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>แล้วสั่ง:</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">sudo</span><span style="color:#9ECBFF;"> systemctl</span><span style="color:#9ECBFF;"> restart</span><span style="color:#9ECBFF;"> networking</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>⸻</p><p>🔍 วิธีเช็กว่าระบบคุณใช้ Netplan หรือไม่:</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">ls</span><span style="color:#9ECBFF;"> /etc/netplan</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>ถ้ามีไฟล์ .yaml → ใช้ Netplan</li><li>ถ้าไม่มี → มักจะใช้ ifupdown (Debian แบบ minimal มักใช้แบบนี้)</li></ul><p>⸻</p><p>✅ สรุป</p><table><thead><tr><th>OS</th><th>Default Network System</th><th>Config Location</th><th>หมายเหตุ</th></tr></thead><tbody><tr><td>Ubuntu</td><td>Netplan</td><td>/etc/netplan/*.yaml</td><td>ใช้ได้กับ 18.04+</td></tr><tr><td>Debian 10+</td><td>Netplan (บางกรณี)</td><td>/etc/netplan/*.yaml</td><td>บาง image ใช้ ifupdown แทน</td></tr><tr><td>Debian</td><td>ifupdown (ดั้งเดิม)</td><td>/etc/network/interfaces</td><td>ต้องเขียนแบบ legacy เอง</td></tr></tbody></table><p>⸻</p><p>⚙️ วิธีที่ 2: ใช้ Dynamic DNS ภายใน Local</p><p>ถ้าคุณใช้ IP แบบ DHCP แล้วไม่อยาก fix IP:</p><p>🔁 ใช้ Script + dnsmasq + hostname</p><ol><li>ติดตั้ง dnsmasq บนเครื่องจริง หรือ VM ตัวใดก็ได้</li><li>ให้ dnsmasq map domain เช่น jenkins.local → ไปยัง hostname ของ VM เช่น jenkins-vm</li><li>ใช้ avahi-daemon / hostname -I ตรวจสอบ IP จริงแล้วอัพเดต DNS record auto</li></ol><p>หรือ</p><p>🧠 ใช้ Script ตรวจ IP แล้วอัพเดตไฟล์ hosts อัตโนมัติ</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#6A737D;">#!/bin/bash</span></span></span>
<span class="line"><span class="line"><span style="color:#E1E4E8;">IP</span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;">$(</span><span style="color:#B392F0;">ping</span><span style="color:#79B8FF;"> -c</span><span style="color:#79B8FF;"> 1</span><span style="color:#9ECBFF;"> jenkins-vm.local</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> grep</span><span style="color:#9ECBFF;"> &quot;PING&quot;</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> awk</span><span style="color:#9ECBFF;"> &#39;{print $3}&#39;</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> tr</span><span style="color:#79B8FF;"> -d</span><span style="color:#9ECBFF;"> &#39;()&#39;</span><span style="color:#E1E4E8;">)</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">sudo</span><span style="color:#9ECBFF;"> sed</span><span style="color:#79B8FF;"> -i</span><span style="color:#9ECBFF;"> &quot;/jenkins.local/d&quot;</span><span style="color:#9ECBFF;"> /etc/hosts</span></span></span>
<span class="line"><span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;</span><span style="color:#E1E4E8;">$IP</span><span style="color:#9ECBFF;"> jenkins.local&quot;</span><span style="color:#F97583;"> |</span><span style="color:#B392F0;"> sudo</span><span style="color:#9ECBFF;"> tee</span><span style="color:#79B8FF;"> -a</span><span style="color:#9ECBFF;"> /etc/hosts</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>แล้ว cron หรือ systemd timer สั่งรันทุกครั้งหลังเปิดเครื่อง</p><p>⸻</p><p>🔁 วิธีที่ 3: ใช้ host.docker.internal หรือ IP แบบ bridge (ถ้าใช้ Docker)</p><p>ถ้า VM ใช้ Docker เป็นหลัก: Docker บน Mac รองรับ host.docker.internal เพื่อชี้กลับไปที่ host โดยไม่ต้องรู้ IP จริง</p><p>แต่ถ้า VM แบบ UTM แยกเป็นเครื่องใหม่จริง ๆ (Bridge Mode) วิธีนี้ใช้ไม่ได้</p><p>⸻</p><p>🏁 สรุปสิ่งที่แนะนำ:</p><table><thead><tr><th>ทางเลือก</th><th>ข้อดี</th><th>ข้อเสีย</th></tr></thead><tbody><tr><td>✅ Fix IP ของ VM</td><td>เสถียร, ไม่พัง, ง่ายสุด</td><td>ต้อง config network ใน VM</td></tr><tr><td>🔁 ใช้ DNS ภายใน (dnsmasq)</td><td>ชื่อจำง่าย, update ได้</td><td>ต้องติดตั้ง DNS server</td></tr><tr><td>🧠 Script update hosts</td><td>ทำงานได้เลย, ไม่ต้อง DNS</td><td>ต้องรัน script เอง, manual</td></tr></tbody></table><p>⸻</p><p>ถ้าบอกได้ว่า VM ใช้ OS อะไร (เช่น Ubuntu Server), แล้วคุณใช้ Mac เป็น host ผมสามารถเขียนไฟล์ config หรือ script ให้ได้เลยแบบเฉพาะเจาะจงครับ</p>`,49)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};